import java.io.*;
import java.nio.file.*;
import java.util.*;

/** In-memory railway domain model with durable CSV persistence. All records are fictional demo data. */
public class RailwayStore {
    public record Train(String id,String name,String from,String to,String status,int passengers,int capacity) {}
    public record Schedule(String trainId,String date,String departure,String arrival,String platform) {}
    public record Ticket(String pnr,String passenger,String trainId,String from,String to,String status) {}
    public record Incident(String id,String trainId,String category,String severity,String description,String status) {}
    private final List<Train> trains=new ArrayList<>(); private final List<Schedule>schedules=new ArrayList<>(); private final List<Ticket>tickets=new ArrayList<>(); private final List<Incident>incidents=new ArrayList<>(); private final List<String>events=new ArrayList<>();
    private final Path dir=Path.of("data");
    public RailwayStore(){loadOrSeed();}
    private void loadOrSeed(){try{if(Files.exists(dir.resolve("trains.csv"))){loadTrains();loadSchedules();loadTickets();loadIncidents();loadEvents();if(trains.isEmpty())seed();}else seed();}catch(Exception e){System.out.println("Warning: could not load saved data ("+e.getMessage()+"). Loading demo records.");trains.clear();schedules.clear();tickets.clear();incidents.clear();events.clear();seed();}}
    private void seed(){trains.add(new Train("RS101","Vande Bharat Express","Vijayawada","Hyderabad","ON TIME",420,600));trains.add(new Train("RS204","Coastal Link","Chennai","Vijayawada","DELAYED",310,500));trains.add(new Train("RS318","Deccan Passenger","Hyderabad","Guntur","ON TIME",185,350));trains.add(new Train("RS422","Night Express","Guntur","Bengaluru","MAINTENANCE",90,450));schedules.add(new Schedule("RS101","2026-10-10","08:30","13:10","2"));schedules.add(new Schedule("RS204","2026-10-10","09:15","14:40","4"));schedules.add(new Schedule("RS318","2026-10-10","10:00","12:05","1"));tickets.add(new Ticket("PNR1001","Ananya","RS101","Vijayawada","Hyderabad","CONFIRMED"));tickets.add(new Ticket("PNR1002","Rahul","RS204","Chennai","Vijayawada","CONFIRMED"));incidents.add(new Incident("INC01","RS204","DELAY","MEDIUM","Service delayed by 18 minutes","OPEN"));incidents.add(new Incident("INC02","RS422","MAINTENANCE","HIGH","Routine inspection required","OPEN"));events.add("RS101 departed Vijayawada platform 2");events.add("RS204 delay alert: 18 minutes");events.add("Maintenance inspection scheduled for RS422");}
    public List<Train> trains(){return Collections.unmodifiableList(trains);} public List<Schedule>schedules(){return Collections.unmodifiableList(schedules);} public List<Ticket>tickets(){return Collections.unmodifiableList(tickets);} public List<Incident>incidents(){return Collections.unmodifiableList(incidents);} public List<String>events(){return Collections.unmodifiableList(events);}
    public Train findTrain(String id){return trains.stream().filter(t->t.id().equalsIgnoreCase(id)).findFirst().orElse(null);} public void addTrain(Train t){if(t.id().isBlank()||t.name().isBlank()||t.from().isBlank()||t.to().isBlank())throw new IllegalArgumentException("Train fields cannot be blank");if(findTrain(t.id())!=null)throw new IllegalArgumentException("Train ID already exists");if(t.passengers()<0||t.capacity()<1||t.passengers()>t.capacity())throw new IllegalArgumentException("Passenger count must be between 0 and capacity");trains.add(t);event("New train record added: "+t.id());}
    public void updateStatus(String id,String status){int i=indexTrain(id);if(i<0)throw new IllegalArgumentException("Train not found");String s=normalStatus(status);Train t=trains.get(i);trains.set(i,new Train(t.id(),t.name(),t.from(),t.to(),s,t.passengers(),t.capacity()));event(id+" status changed to "+s);}
    public void addSchedule(Schedule s){if(findTrain(s.trainId())==null)throw new IllegalArgumentException("Train ID does not exist");if(s.date().isBlank()||s.departure().isBlank()||s.arrival().isBlank()||s.platform().isBlank())throw new IllegalArgumentException("Schedule fields cannot be blank");boolean conflict=schedules.stream().anyMatch(x->x.date().equals(s.date())&&x.departure().equals(s.departure())&&x.platform().equals(s.platform()));if(conflict)throw new IllegalArgumentException("Platform conflict: another train has same date, departure time and platform");schedules.add(s);event("Schedule added for "+s.trainId()+" on platform "+s.platform());}
    public void addTicket(Ticket t){if(findTrain(t.trainId())==null)throw new IllegalArgumentException("Train ID does not exist");Train tr=findTrain(t.trainId());long sold=tickets.stream().filter(x->x.trainId().equalsIgnoreCase(t.trainId())&&x.status().equals("CONFIRMED")).count();if(sold>=tr.capacity()-tr.passengers())throw new IllegalArgumentException("No demo ticket capacity remaining for this train");if(tickets.stream().anyMatch(x->x.pnr().equalsIgnoreCase(t.pnr())))throw new IllegalArgumentException("PNR already exists");tickets.add(t);event("Ticket "+t.pnr()+" created for "+t.trainId());}
    public void addIncident(Incident i){if(findTrain(i.trainId())==null)throw new IllegalArgumentException("Train ID does not exist");if(incidents.stream().anyMatch(x->x.id().equalsIgnoreCase(i.id())))throw new IllegalArgumentException("Incident ID already exists");incidents.add(i);event("Incident "+i.id()+" reported for "+i.trainId()+": "+i.category());}
    public void closeIncident(String id){for(int i=0;i<incidents.size();i++){Incident x=incidents.get(i);if(x.id().equalsIgnoreCase(id)){incidents.set(i,new Incident(x.id(),x.trainId(),x.category(),x.severity(),x.description(),"CLOSED"));event("Incident "+id+" closed");return;}}throw new IllegalArgumentException("Incident not found");}
    public void event(String e){events.add(e);}
    private int indexTrain(String id){for(int i=0;i<trains.size();i++)if(trains.get(i).id().equalsIgnoreCase(id))return i;return -1;}
    private String normalStatus(String s){String v=s.trim().toUpperCase(Locale.ROOT);if(!Set.of("ON TIME","DELAYED","CANCELLED","MAINTENANCE","ARRIVED","BOARDING").contains(v))throw new IllegalArgumentException("Use ON TIME, DELAYED, CANCELLED, MAINTENANCE, ARRIVED or BOARDING");return v;}
    public void save() throws IOException {Files.createDirectories(dir);write("trains.csv","id,name,from,to,status,passengers,capacity",trains.stream().map(t->row(t.id(),t.name(),t.from(),t.to(),t.status(),t.passengers(),t.capacity())).toList());write("schedules.csv","trainId,date,departure,arrival,platform",schedules.stream().map(s->row(s.trainId(),s.date(),s.departure(),s.arrival(),s.platform())).toList());write("tickets.csv","pnr,passenger,trainId,from,to,status",tickets.stream().map(t->row(t.pnr(),t.passenger(),t.trainId(),t.from(),t.to(),t.status())).toList());write("incidents.csv","id,trainId,category,severity,description,status",incidents.stream().map(i->row(i.id(),i.trainId(),i.category(),i.severity(),i.description(),i.status())).toList());write("events.csv","event",events.stream().map(e->row(e)).toList());}
    private void write(String name,String header,List<String>rows)throws IOException{Path target=dir.resolve(name),tmp=dir.resolve(name+".tmp");try(BufferedWriter w=Files.newBufferedWriter(tmp)){w.write(header);w.newLine();for(String r:rows){w.write(r);w.newLine();}}try{Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException ex){Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING);}}
    private String row(Object...v){List<String>o=new ArrayList<>();for(Object x:v){String s=String.valueOf(x);o.add("\""+s.replace("\"","\"\"")+"\"");}return String.join(",",o);}
    private List<List<String>>read(String file)throws IOException{Path p=dir.resolve(file);if(!Files.exists(p))return List.of();List<List<String>>out=new ArrayList<>();for(String line:Files.readAllLines(p)){List<String>row=new ArrayList<>();StringBuilder cell=new StringBuilder();boolean quote=false;for(int i=0;i<line.length();i++){char c=line.charAt(i);if(c=='"'){if(quote&&i+1<line.length()&&line.charAt(i+1)=='"'){cell.append('"');i++;}else quote=!quote;}else if(c==','&&!quote){row.add(cell.toString());cell.setLength(0);}else cell.append(c);}row.add(cell.toString());out.add(row);}return out;}
    private void loadTrains()throws IOException{List<List<String>>r=read("trains.csv");for(int i=1;i<r.size();i++){List<String>x=r.get(i);if(x.size()>=7)trains.add(new Train(x.get(0),x.get(1),x.get(2),x.get(3),x.get(4),Integer.parseInt(x.get(5)),Integer.parseInt(x.get(6))));else if(x.size()==6)trains.add(new Train(x.get(0),x.get(1),x.get(2),x.get(3),x.get(4),Integer.parseInt(x.get(5)),Math.max(500,Integer.parseInt(x.get(5)))));}}
    private void loadSchedules()throws IOException{List<List<String>>r=read("schedules.csv");for(int i=1;i<r.size();i++){List<String>x=r.get(i);if(x.size()>=5)schedules.add(new Schedule(x.get(0),x.get(1),x.get(2),x.get(3),x.get(4)));}}
    private void loadTickets()throws IOException{List<List<String>>r=read("tickets.csv");for(int i=1;i<r.size();i++){List<String>x=r.get(i);if(x.size()>=6)tickets.add(new Ticket(x.get(0),x.get(1),x.get(2),x.get(3),x.get(4),x.get(5)));}}
    private void loadIncidents()throws IOException{List<List<String>>r=read("incidents.csv");for(int i=1;i<r.size();i++){List<String>x=r.get(i);if(x.size()>=6)incidents.add(new Incident(x.get(0),x.get(1),x.get(2),x.get(3),x.get(4),x.get(5)));}}
    private void loadEvents()throws IOException{List<List<String>>r=read("events.csv");for(int i=1;i<r.size();i++)if(!r.get(i).isEmpty())events.add(r.get(i).get(0));}
}
